import{_ as s,o as t,c as a,a3 as o}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Command Resolution","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Command Resolution | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/command-resolve"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/command-resolve"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/command-resolve"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/command-resolve"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/command-resolve"}]]},"headers":[],"relativePath":"clice/design/command-resolve.md","filePath":"en/clice/design/command-resolve.md","lastUpdated":1794738697000}'),n={name:"clice/design/command-resolve.md"};function i(r,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="command-resolution" tabindex="-1">Command Resolution <a class="header-anchor" href="#command-resolution" aria-label="Permalink to &quot;Command Resolution&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>A language server learns how to compile each file from the compilation database, usually a <code>compile_commands.json</code> the build system writes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I../include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNDEBUG</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/foo.cpp</span></span></code></pre></div><p>It cannot run that command as it stands:</p><ul><li><strong>It is a driver command.</strong> <code>g++</code> picks a frontend, a standard library and system headers; clice runs Clang&#39;s frontend, which needs all of that spelled out — the target, the system include directories, the default language standard. None of it is in the database: the compiler supplies it.</li><li><strong>It carries options that change nothing a language server sees</strong>: <code>-g</code>, <code>-c</code>, <code>-o</code>, dependency files.</li><li><strong>It repeats itself.</strong> Ten thousand units of one target share a compiler and its options and differ in include paths and macros.</li></ul><p>What is missing hurts most: without the system headers, <code>#include &lt;vector&gt;</code> is &quot;file not found&quot; — consistently among clangd&#39;s most reported problems (<a href="https://github.com/clangd/clangd/issues/1262" target="_blank" rel="noreferrer">clangd#1262</a>, <a href="https://github.com/clangd/clangd/issues/1691" target="_blank" rel="noreferrer">clangd#1691</a>). clangd asks a compiler only when <code>--query-driver</code> names it, which the user has to find out and configure (<a href="https://github.com/clangd/clangd/issues/1219" target="_blank" rel="noreferrer">clangd#1219</a>). clice asks every command&#39;s compiler, recognizes its family, and keeps the number of questions small.</p><h2 id="classifying-options" tabindex="-1">Classifying Options <a class="header-anchor" href="#classifying-options" aria-label="Permalink to &quot;Classifying Options&quot;">​</a></h2><p>Each command is parsed once, with Clang&#39;s own option table, by option ID: every spelling of an option — joined, separate, cl&#39;s <code>/</code> — classifies alike. Each option is either left out or kept in a category:</p><ul><li><strong>Left out</strong>: what only the build reads — outputs, compile mode, dependency files, timings, the assembler&#39;s options, GCC&#39;s module mapper, cl&#39;s module interface outputs — and what only shapes the generated code (<code>-g</code>, <code>-ffunction-sections</code>). Options that look like code generation but change the preprocessor stay: <code>-O</code> defines <code>__OPTIMIZE__</code>, <code>-fPIC</code> defines <code>__PIC__</code>, and <code>-fsanitize=address</code> changes what <code>__has_feature</code> answers.</li><li><strong>Diagnostics</strong>: warning options. They change which diagnostics show, nothing else.</li><li><strong>User content</strong>: what one file needs — include paths, macros, forced includes. It does not change what the compiler answers about itself.</li><li><strong>Semantic</strong>: the rest — <code>-std</code>, <code>--target</code>, <code>-march</code> — which the compiler&#39;s answers depend on.</li><li><strong>Precompiled</strong>: the PCH a command reads or writes, and whether it writes a module, which clice builds itself.</li><li><strong>Input</strong>, the file, in a slot of its own; and <strong>unknown</strong> options, which count in the command&#39;s identity.</li></ul><p>The parsed commands live in one table, each once. Everything downstream — querying, rules, rendering — reads the structured form, and a command&#39;s identity is its <strong>command hash</strong>: every argument it keeps, the input&#39;s position and the working directory. The index records each unit&#39;s command hash, and the user&#39;s choice of an entry names it.</p><p>The classification is also what keeps questions few: a compiler&#39;s answer does not depend on the user content, so files differing only in it share one answer. Tens of thousands of files come down to a few dozen questions.</p><h2 id="rules-members-and-hosts" tabindex="-1">Rules, Members and Hosts <a class="header-anchor" href="#rules-members-and-hosts" aria-label="Permalink to &quot;Rules, Members and Hosts&quot;">​</a></h2><p>The rules of <code>clice.toml</code> decide, under the active build configuration, what the databases&#39; entries become; every consumer — the editor, the dependency scan, the background index, the command line — asks the project, never a database directly.</p><ul><li><strong>Entries.</strong> A file&#39;s entries in build order: the databases its matching rules name first, then the other rules&#39;, then the discovered ones. The first is the default; the user can pick another. A rule decides priority only: no entry disappears because a pattern does not name its file.</li><li><strong>Edits.</strong> Every matching rule&#39;s <code>remove</code> and <code>append</code>, in declaration order. A command a file takes from another — a header from its host — is edited by the rules of both files, so a header sees the macros its host compiles with.</li><li><strong>Members.</strong> The translation units of the build: the files with entries, the sources a rule&#39;s <code>default_command</code> covers, and the provisional members (below). A header a database lists is a member too, and is indexed as a unit of its own.</li><li><strong>Hosts.</strong> A header without a command of its own compiles in a unit that includes it, of a language the header can be part of (never C for a <code>.hpp</code>). The candidates rank by the databases the header&#39;s own rules name, then a shared stem, then the same directory, then the distance by path; the first whose compile actually enters the header hosts it. See <a href="./compilation-context">Compilation Context</a>.</li><li><strong>Borrowed commands.</strong> A file with neither an entry, a host nor a <code>default_command</code> borrows a nearby unit&#39;s command of its language: one in its directory, the one sharing its stem first, else for a header the unit whose include directories contain it, else the nearest. It is labeled so, and its diagnostics about missing files say the command was borrowed.</li><li><strong>Provisional members.</strong> A source of the project the user opens or saves that no database lists and no unit includes — one created after the database was written, or one of a project without a database — joins the build, under a borrowed command or clice&#39;s own when there is none to borrow: it is indexed, provides its module and hosts the headers it includes. A source a unit includes, such as the part of a unity build, compiles in that unit&#39;s context instead. The record outlives restarts; a database that lists the file takes over.</li></ul><h3 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h3><p>A configuration that declares no database and no <code>default_command</code> discovers them: the <code>compile_commands.json</code> of the project root and of its immediate subdirectories, and when a file is opened, those in the directories between it and the root. A directory with a <code>clice.toml</code> or <code>.clice/config.toml</code> of its own is another project. A link to a database found already is the same database. The server keeps looking on its poll, so a database generated later loads when it appears. As soon as a rule declares a source, discovery is off: the declaration is the whole intent.</p><h2 id="asking-the-compiler" tabindex="-1">Asking the Compiler <a class="header-anchor" href="#asking-the-compiler" aria-label="Permalink to &quot;Asking the Compiler&quot;">​</a></h2><p>Each compiler family is asked in its own way, once per distinct question, and the answer is cached:</p><ul><li><strong>GCC-style drivers</strong> (GCC, clang, Apple clang, emcc, zig, cross and bare-metal GCC) preprocess an empty file of the input&#39;s language with the command&#39;s own flags, verbosely and printing their macros (<code>-E -dM -v</code>). One run answers everything: a clang driver prints the frontend job clice runs; a GCC prints its target, its header search list and the options its specs add, and clang&#39;s driver builds the frontend command pinned to that target with GCC&#39;s search list. The macros give the default language standard. Whether a driver is clang or GCC is told by its answer, never by its name: <code>/usr/bin/c++</code> is clang on macOS.</li><li><strong>cl and clang-cl</strong> preprocess a file naming <code>_MSVC_LANG</code> and <code>_MSC_FULL_VER</code>, which give the standard and, for cl, the version; clang&#39;s driver in cl mode builds the command.</li><li><strong>nvcc</strong>&#39;s dry run gives the CUDA root, the host compiler, nvcc&#39;s macros and its header directories; a GCC or clang host is asked as above, and clang&#39;s driver builds a CUDA command.</li><li><strong>A compiler clice does not run</strong> — a rule&#39;s <code>query_toolchain = false</code>, or one whose query fails — leaves the command to clang&#39;s own driver, which reads it as a clang installed under that name would; a failed query is shown at the top of each file it concerns.</li></ul><p>What the answer cannot carry over is adjusted to clang. GCC&#39;s private include directory mixes GCC&#39;s versions of clang&#39;s builtin headers, which clang cannot parse, with headers only GCC has (<code>omp.h</code>): clice keeps the directory and hides the files clang&#39;s own stand in for; CPU and ABI names clang does not know are dropped; the warnings GCC, cl and nvcc make errors stay warnings, since clang warns of things those compilers never report; GCC&#39;s <code>-fmodules</code> means C++20 modules, not clang&#39;s header modules. A launcher in front of the compiler (ccache, sccache, distcc, icecc) is taken off first.</p><p>At startup, every distinct question of the build is asked in parallel during the dependency scan, so the first compiles find their answers cached.</p><h2 id="search-paths" tabindex="-1">Search Paths <a class="header-anchor" href="#search-paths" aria-label="Permalink to &quot;Search Paths&quot;">​</a></h2><p>The frontend command&#39;s include directories are sorted into four tiers as Clang sorts them — quoted (<code>-iquote</code>), angled (<code>-I</code>), system and after (<code>-idirafter</code>) — and deduplicated the way Clang does: a directory both angled and system is searched where the system group puts it. The same order is what clice&#39;s own include search, the dependency scan and <code>#include</code> completion use, so <code>#include_next</code> and same-named headers resolve to the files the compiler would find.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><strong>Why does a GCC command parse as clang?</strong> clice&#39;s frontend is clang. The macros naming the compiler stay clang&#39;s — <code>__clang__</code> is defined — because GCC&#39;s would send clang down branches written for GCC alone, full of builtins clang cannot parse. Everything that describes the build follows the real compiler: the target, the search list, the language standard, the macros its configuration adds.</li><li><strong>Why ask by the name the command uses, not the resolved path?</strong> A driver behaves by its name: <code>clang++</code> is a link to <code>clang</code> that compiles C++, and <code>arm-none-eabi-g++</code> names its target. Resolving the link would lose both.</li><li><strong>Why must the search order match Clang exactly?</strong> Which of two same-named headers a file includes, and where <code>#include_next</code> continues, follow from the order. Any difference would show the user other code than the compiler compiles.</li></ul><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>Discovery never scans the tree.</strong> A nested project&#39;s database loads when one of its files opens; a rule naming the database covers it from the start.</li><li><strong>Only the editor adds unlisted files to the build.</strong> A source that appears on disk any other way, that no database lists and no rule&#39;s <code>default_command</code> covers, stays outside the build until it is opened or saved, or a regenerated database lists it.</li><li><strong>GCC-only code parses as clang sees it</strong>: GCC-only builtins, <code>__float128</code> where clang lacks it, nested functions show clang&#39;s errors.</li><li><strong>CUDA parses as clang&#39;s CUDA sees it</strong>: code only nvcc accepts shows clang&#39;s errors.</li><li><strong>A driver that answers neither as clang nor as GCC</strong> — Intel&#39;s classic <code>icc</code>, other vendors&#39; compilers — gets clang&#39;s defaults for the machine, and the error says so.</li><li><strong>Only the common launchers are recognized.</strong> Another launcher is taken for the compiler; strip it from the database.</li><li><strong>Header maps are not read</strong> by clice&#39;s own include search (dependencies, completion, links), though the compile applies them.</li><li><strong>Cygwin symlinks among headers are not followed</strong>: clice&#39;s clang reads the link file itself.</li><li><strong>Commands written for other tools leave out the directories clice hides files in.</strong> <code>clice command convert</code> writes the command without GCC&#39;s private include directory and another clang&#39;s builtin headers; <code>clice command &lt;file&gt; --json</code> lists what each hides.</li></ul>',28)])])}const u=s(n,[["render",i]]);export{g as __pageData,u as default};
